                <span class="ic-revenue">{{ fmtM(n(store.revenue)) }}</span>
              </div>
              <div class="ic-right-col">
                <div class="ic-margin-ring">
                  <svg width="64" height="64" viewBox="0 0 52 52">
                    <circle cx="26" cy="26" r="20" fill="none" stroke="rgba(255,255,255,0.2)" stroke-width="4"/>
                    <circle cx="26" cy="26" r="20" fill="none" stroke="rgba(255,255,255,0.85)" stroke-width="4"
                            :stroke-dasharray="`${Math.min(rowMargin(store),1) * 125.6} 125.6`"
                            stroke-linecap="round" transform="rotate(-90 26 26)"/>
                  </svg>
                  <span class="ic-margin-pct">{{ (rowMargin(store) * 100).toFixed(1) }}%</span>
                </div>
                <span v-if="rowOpProfit(store) < 0" class="ic-risk-badge ic-loss">ЗБИТОК</span>
                <span v-else-if="rowOpProfit(store) < n(store.profit) * 0.08" class="ic-risk-badge ic-risk">РИЗИК</span>
              </div>
            </div>

            <!-- Донат + легенда -->
            <div class="ic-body">
              <div class="ic-donut-area">
                <svg viewBox="0 0 120 120" style="width:120px;height:120px;flex-shrink:0">
                  <path v-for="seg in storePieSegs(store)" :key="seg.label"
                        :d="seg.path" :fill="seg.color" stroke="#fff" stroke-width="1.5"/>
                  <!-- Центр -->
                  <circle cx="60" cy="60" r="26" fill="#fff"/>
                  <!-- При збитку — явна позначка замість маржі -->
                  <template v-if="storePieSegs(store).length && storePieSegs(store)[0].isLoss">
                    <text x="60" y="56" text-anchor="middle" fill="#ef4444"
                          font-size="7" font-weight="800" font-family="Arial,sans-serif">
                      ЗБИТОК
                    </text>
                    <text x="60" y="68" text-anchor="middle" fill="#ef4444"
                          font-size="8" font-weight="700" font-family="Arial,sans-serif">
                      {{ fmtM(rowOpProfit(store)) }}
                    </text>
                  </template>
                  <template v-else>
                    <text x="60" y="56" text-anchor="middle" fill="#1e293b"
                          font-size="9" font-weight="800" font-family="Arial,sans-serif">
                      {{ (rowMargin(store) * 100).toFixed(1) }}%
                    </text>
                    <text x="60" y="68" text-anchor="middle" fill="#94a3b8"
                          font-size="7" font-family="Arial,sans-serif">маржа
                    </text>
                  </template>
                </svg>
              </div>
              <div class="ic-legend-area">
                <div v-for="seg in storePieSegs(store)" :key="seg.label" class="icl-row">
                  <div class="icl-left">
                    <span class="icl-dot" :style="{background: seg.color}"></span>
                    <span class="icl-name">{{ seg.label }}</span>
                  </div>
                  <div class="icl-bar-track">
                    <div class="icl-bar-fill"
                         :style="{width: (seg.value / storePieSegs(store)[0].value * 100) + '%', background: seg.color}">
                    </div>
                  </div>
                  <span class="icl-num">{{ fmt(seg.value) }}</span>
                  <span class="icl-pct">{{ (seg.value / seg.total * 100).toFixed(1) }}%</span>
                </div>
              </div>
            </div>

            <!-- Метрики -->
            <div class="ic-metrics">
              <div class="ic-metric">
                <span class="icm-label">Прибуток</span>
                <span class="icm-val">{{ fmtM(n(store.profit)) }}</span>
              </div>
              <div class="ic-metric">
                <span class="icm-label">Витрати</span>
                <span class="icm-val">{{ fmtM(rowExpenses(store)) }}</span>
              </div>
              <div class="ic-metric" :class="rowOpProfit(store) >= 0 ? 'icm-green' : 'icm-red'">
                <span class="icm-label">Оп. прибуток</span>
                <span class="icm-val">{{ fmtM(rowOpProfit(store)) }}</span>
              </div>
            </div>

          </div>
        </div>
      </section>

      <div class="divider"></div>

      <!-- ── 13-14. Офіс та Склад ───────────────────────── -->
      <section class="budget-section" v-if="ofisKyiv || skladKyiv">
        <div class="section-header"><h2 class="section-title">Офіс та Склад Київ</h2></div>
        <div class="office-grid">

          <!-- Офіс Київ -->
          <div class="office-card" v-if="ofisKyiv">
            <div class="office-header office-header--purple">
              <div class="oh-icon">🏢</div>
              <div class="oh-info">
                <span class="oh-title">{{ $t('budget.sectionOfficePie') }}</span>
                <span class="oh-total">Витрати: {{ fmtM(rowExpenses(ofisKyiv)) }}</span>
              </div>
              <div class="oh-stats">
                <div class="oh-stat"><span class="oh-stat-l">Доходи</span><span
                    class="oh-stat-v">{{ fmtM(n(ofisKyiv.revenue)) }}</span></div>
                <div class="oh-stat"><span class="oh-stat-l">Прибуток</span><span
                    class="oh-stat-v">{{ fmtM(n(ofisKyiv.profit)) }}</span></div>
              </div>
            </div>
            <div class="office-bars">
              <div v-for="item in officeBars(ofisKyiv)" :key="item.label" class="ob-row">
                <div class="ob-label-col">
                  <span class="ob-dot" :style="{background: item.color}"></span>
                  <span class="ob-label">{{ item.label }}</span>
                </div>
                <div class="ob-track">
                  <div class="ob-fill" :style="{width: item.pct + '%', background: item.color}"></div>
                </div>
                <span class="ob-val">{{ fmt(item.value) }}</span>
                <span class="ob-pct">{{ item.sharePct }}%</span>
              </div>
            </div>
          </div>

          <!-- Склад Київ -->
          <div class="office-card" v-if="skladKyiv">
            <div class="office-header office-header--teal">
              <div class="oh-icon">🏭</div>
              <div class="oh-info">
                <span class="oh-title">{{ $t('budget.sectionWarehousePie') }}</span>
                <span class="oh-total">Витрати: {{ fmtM(rowExpenses(skladKyiv)) }}</span>
              </div>
              <div class="oh-stats">
                <div class="oh-stat"><span class="oh-stat-l">Доходи</span><span
                    class="oh-stat-v">{{ fmtM(n(skladKyiv.revenue)) }}</span></div>
                <div class="oh-stat"><span class="oh-stat-l">Прибуток</span><span
                    class="oh-stat-v">{{ fmtM(n(skladKyiv.profit)) }}</span></div>
              </div>
            </div>
            <div class="office-bars">
              <div v-for="item in officeBars(skladKyiv)" :key="item.label" class="ob-row">
                <div class="ob-label-col">
                  <span class="ob-dot" :style="{background: item.color}"></span>
                  <span class="ob-label">{{ item.label }}</span>
                </div>
                <div class="ob-track">
                  <div class="ob-fill" :style="{width: item.pct + '%', background: item.color}"></div>
                </div>
                <span class="ob-val">{{ fmt(item.value) }}</span>
                <span class="ob-pct">{{ item.sharePct }}%</span>
              </div>
            </div>
          </div>

        </div>
      </section>

    </div>
  </div>
</template>

<script>
import {markRaw} from 'vue'
import {
  Chart, ArcElement, BarElement, CategoryScale, LinearScale,
  Tooltip, Legend, DoughnutController, BarController,
} from 'chart.js'
import {BUDGET_URL} from '@/config/managers.config'

Chart.register(ArcElement, BarElement, CategoryScale, LinearScale,
    Tooltip, Legend, DoughnutController, BarController)

// ── Константы ───────────────────────────────────────────
const SPECIAL = new Set([
  'МЕРЕЖА (ФОТ деталізація)', 'Офіс Київ', 'Склад Київ',
  'Тендер', 'Сервер', 'Склад Смольная', 'Склад Київ ТМЦ',
  'Склад', 'Офіс', 'Кібер-Бульвар',
])

const EXPENSE_FIELDS = [
  'rent', 'security', 'transport', 'fuel', 'insurance', 'other_services',
  'utilities', 'logistics', 'communication', 'bank_fees', 'writeoffs',
  'repr_expenses', 'repairs', 'tools', 'salary', 'salary_other', 'salary_travel',
  'marketing', 'taxes',
]

const MAINTAIN_FIELDS = [
  'rent', 'security', 'transport', 'fuel', 'insurance', 'other_services',
  'utilities', 'logistics', 'communication', 'bank_fees', 'writeoffs', 'repr_expenses',
]

const PIE_COLORS = [
  '#6366f1', '#22c55e', '#f59e0b', '#ef4444', '#14b8a6',
  '#8b5cf6', '#f97316', '#06b6d4', '#84cc16', '#ec4899',
  '#a78bfa', '#fb923c', '#34d399', '#fbbf24',
]

export default {
  name: 'BudgetPage',

  directives: {
    clickOutside: {
      mounted(el, binding) {
        el._clickOutside = (e) => { if (!el.contains(e.target)) binding.value(e) }
        document.addEventListener('click', el._clickOutside)
      },
      unmounted(el) {
        document.removeEventListener('click', el._clickOutside)
      },
    },
  },

  data() {
    return {
      loading: true,
      error: null,
      rawData: [],
      searchQuery: '',
      charts: markRaw({}),
      storeCharts: markRaw({}),
      observer: null,
      screenWidth: typeof window !== 'undefined' ? window.innerWidth : 1024,
      profitSortBy: 'op',
      salSortBy: 'profit', // 'pct' | 'profit'
      selectedPeriod: '',
      periodMenuOpen: false,
    }
  },

  computed: {
    isMobile() {
      return this.screenWidth < 640
    },

    availablePeriods() {
      const seen = new Set()
      return this.rawData
          .map(r => r.time)
          .filter(t => t && !seen.has(t) && seen.add(t))
    },

    // Єдине джерело даних для всіх computed — фільтрується за обраним періодом
    filteredData() {
      if (!this.selectedPeriod) return this.rawData
      return this.rawData.filter(r => r.time === this.selectedPeriod)
    },

    period() {
      return this.selectedPeriod || this.rawData[0]?.time || ''
    },

    storeRows() {
      return this.filteredData.filter(r => !SPECIAL.has(r.store))
    },

    fotRow() {
      return this.filteredData.find(r => r.store === 'МЕРЕЖА (ФОТ деталізація)') || {}
    },

    ofisKyiv() {
      return this.filteredData.find(r => r.store === 'Офіс Київ') || null
    },

    skladKyiv() {
      return this.filteredData.find(r => r.store === 'Склад Київ') || null
    },

    // ── KPI ───────────────────────────────────────────────
    kpiBase() {
      const rows = this.allExpRows
      const rev = rows.reduce((s, r) => s + this.n(r.revenue), 0)
      const prof = rows.reduce((s, r) => s + this.n(r.profit), 0)
      const exp = rows.reduce((s, r) => s + this.rowExpenses(r), 0)
      return {rev, prof, exp, net: prof - exp}
    },

    kpiCards() {
      const {rev, prof, exp, net} = this.kpiBase
      return [
        {
          key: 'rev', label: this.$t('budget.kpiRevenue'),
          value: this.fmt(rev), icon: 'mdi-cash-multiple',
          cls: 'kpi-blue', pct: 100, ringColor: 'rgba(255,255,255,0.6)',
          sub: `100% від доходу`,
        },
        {
          key: 'prof', label: this.$t('budget.kpiProfit'),
          value: this.fmt(prof), icon: 'mdi-trending-up',
          cls: 'kpi-green',
          pct: Math.min(rev > 0 ? (prof / rev * 100) : 0, 100),
          ringColor: 'rgba(255,255,255,0.6)',
          sub: `${(rev > 0 ? prof / rev * 100 : 0).toFixed(1)}% від доходу`,
        },
        {
          key: 'exp', label: this.$t('budget.kpiExpenses'),
          value: this.fmt(exp), icon: 'mdi-cash-minus',
          cls: 'kpi-orange',
          pct: Math.min(rev > 0 ? (exp / rev * 100) : 0, 100),
          ringColor: 'rgba(255,255,255,0.6)',
          sub: `${(rev > 0 ? exp / rev * 100 : 0).toFixed(1)}% від доходу`,
        },
        {
          key: 'net', label: this.$t('budget.kpiNet'),
          value: this.fmt(net), icon: net >= 0 ? 'mdi-star-circle' : 'mdi-alert',
          cls: net >= 0 ? 'kpi-purple' : 'kpi-red',
          pct: Math.min(rev > 0 ? Math.abs(net / rev * 100) : 0, 100),
          ringColor: 'rgba(255,255,255,0.6)',
          sub: `${(rev > 0 ? net / rev * 100 : 0).toFixed(2)}% від доходу`,
        },
      ]
    },

    // ── Treemap data ──────────────────────────────────────
    revenueTreemap() {
      return this.filteredData
          .filter(r => r.store !== 'МЕРЕЖА (ФОТ деталізація)' && this.n(r.revenue) > 0)
          .map(r => ({store: r.store, value: this.n(r.revenue)}))
          .sort((a, b) => b.value - a.value)
    },

    expenseTreemap() {
      return this.filteredData
          .filter(r => r.store !== 'МЕРЕЖА (ФОТ деталізація)' && this.rowExpenses(r) > 0)
          .map(r => ({store: r.store, value: this.rowExpenses(r)}))
          .sort((a, b) => b.value - a.value)
    },

    revenueTreemapCells() {
      const COLORS = [
        '#4f46e5','#2563eb','#0891b2','#059669','#7c3aed',
        '#b45309','#be185d','#0d9488','#1d4ed8','#6d28d9',
        '#047857','#b91c1c','#0369a1','#4338ca','#0e7490',
        '#065f46','#7e22ce','#92400e','#1e40af','#166534',
        '#831843','#1e3a8a','#134e4a','#3730a3','#78350f',
      ]
      return this.computeTreemapLayout(this.revenueTreemap, COLORS, this.isMobile)
    },

    expenseTreemapCells() {
      const COLORS = [
        '#dc2626','#ea580c','#d97706','#b45309','#92400e',
        '#9f1239','#7f1d1d','#c2410c','#a16207','#78350f',
        '#6366f1','#7c3aed','#0891b2','#059669','#1d4ed8',
        '#be185d','#0d9488','#4338ca','#0e7490','#166534',
        '#64748b','#334155','#1e293b','#4b5563','#374151',
      ]
      return this.computeTreemapLayout(this.expenseTreemap, COLORS, this.isMobile)
    },

    // Все строки для финансовых расчётов (включая Офіс, Склад, ІМ)
    allExpRows() {
      return this.filteredData.filter(r => r.store !== 'МЕРЕЖА (ФОТ деталізація)')
    },

    // ── Pie charts data ───────────────────────────────────
    expCatData() {
      const rows = this.allExpRows
      const sum = (fields) => rows.reduce((s, r) => s + fields.reduce((ss, f) => ss + this.n(r[f]), 0), 0)
      return [
        {label: this.$t('budget.catMaintain'), value: sum(MAINTAIN_FIELDS), color: PIE_COLORS[0]},
        {label: this.$t('budget.catRepairs'), value: sum(['repairs', 'tools']), color: PIE_COLORS[1]},
        {
          label: this.$t('budget.catPersonnel'),
          value: sum(['salary', 'salary_other', 'salary_travel']),
          color: PIE_COLORS[2]
        },
        {label: this.$t('budget.catMarketing'), value: sum(['marketing']), color: PIE_COLORS[3]},
        {label: this.$t('budget.catTaxes'), value: sum(['taxes']), color: PIE_COLORS[4]},
      ].filter(d => d.value > 0).sort((a, b) => b.value - a.value)
    },

    maintainData() {
      const rows = this.allExpRows
      const labels = [
        'Оренда', 'Охорона', 'Автотранспорт', 'ПММ', 'Страхування',
        'Послуги інші', 'Комунальні', 'Логістика', "Зв'язок",
        'РКО', 'Втрати/списання', 'Представницькі',
      ]
      return MAINTAIN_FIELDS.map((f, i) => ({
        label: labels[i],
        value: rows.reduce((s, r) => s + this.n(r[f]), 0),
        color: PIE_COLORS[i % PIE_COLORS.length],
      })).filter(d => d.value > 0).sort((a, b) => b.value - a.value)
    },

    fotData() {
      // Усі компоненти ФОТ — з рядка «МЕРЕЖА (ФОТ деталізація)»,
      // який містить сітковий бреакдаун по типах оплати.
      // salary_other і salary_travel відсутні в МЕРЕЖА →
      // беремо їх сумою по всіх рядках (вони не входять до основних 5 компонентів).
      const fot = this.fotRow
      const rows = this.allExpRows
      const salOther = rows.reduce((s, r) => s + this.n(r.salary_other), 0)
      const salTravel = rows.reduce((s, r) => s + this.n(r.salary_travel), 0)
      return [
        {label: 'Ставка', value: this.n(fot.salary_rate), color: PIE_COLORS[0]},
        {label: '% від продажу', value: this.n(fot.salary_pct_sales), color: PIE_COLORS[1]},
        {label: 'Премії та бонуси', value: this.n(fot.salary_bonuses), color: PIE_COLORS[2]},
        {label: 'Поза штатом', value: this.n(fot.salary_freelance), color: PIE_COLORS[3]},
        {label: 'Відпускні', value: this.n(fot.salary_vacation), color: PIE_COLORS[4]},
        {label: 'Інші витрати персоналу', value: salOther, color: PIE_COLORS[5]},
        {label: 'Відрядження', value: salTravel, color: PIE_COLORS[6]},
      ].filter(d => d.value > 0).sort((a, b) => b.value - a.value)
    },

    // ── 3D Pie computed ───────────────────────────────────
    expCatPie3d() {
      return this.buildPie3d(this.expCatData)
    },
    maintainPie3d() {
      return this.buildPie3d(this.maintainData)
    },
    fotPie3d() {
      return this.buildPie3d(this.fotData)
    },

    // ── Офіс та Склад pie ────────────────────────────────
    ofisData() {
      if (!this.ofisKyiv) return []
      const r = this.ofisKyiv
      return EXPENSE_FIELDS.map((f, i) => ({
        label: this.expFieldLabel(f), value: this.n(r[f]),
        color: PIE_COLORS[i % PIE_COLORS.length],
      })).filter(d => d.value > 0)
    },

    skladData() {
      if (!this.skladKyiv) return []
      const r = this.skladKyiv
      return EXPENSE_FIELDS.map((f, i) => ({
        label: this.expFieldLabel(f), value: this.n(r[f]),
        color: PIE_COLORS[i % PIE_COLORS.length],
      })).filter(d => d.value > 0)
    },

    // Об'єднані дані для горизонтального графіку прибутку
    combinedProfitRows() {
      const rows = this.storeRows.map(r => ({
        ...r,
        _op:  this.rowOpProfit(r),
        _net: this.n(r.net_profit),
      }))
      return this.profitSortBy === 'net'
          ? rows.sort((a, b) => b._net - a._net)
          : rows.sort((a, b) => b._op  - a._op)
    },
    combinedProfitMax() {
      return Math.max(...this.combinedProfitRows.map(r => Math.max(Math.abs(r._op), Math.abs(r._net))), 1)
    },

    // ── Rankings (sorted) ─────────────────────────────────
    storesSortedByMargin() {
      // Маржинальність = валовий прибуток / дохід
      return [...this.storeRows]
          .map(r => ({...r, _margin: this.n(r.revenue) > 0 ? this.n(r.profit) / this.n(r.revenue) : 0}))
          .sort((a, b) => b._margin - a._margin)
    },

    storesSortedByRentab() {
      // Рентабельність = (валовий прибуток - витрати) / дохід
      return [...this.storeRows]
          .map(r => ({
            ...r,
            _rentab: this.rowProfitability(r),
            _rentabAfter: this.rowProfitabilityAfter(r),
          }))
          .sort((a, b) => b._rentab - a._rentab)
    },

    storesSortedByOpProfit() {
      // Прибуток від діяльності = валовий прибуток - операційні витрати
      return [...this.storeRows]
          .map(r => ({...r, _op: this.rowOpProfit(r)}))
          .sort((a, b) => b._op - a._op)
    },

    storesSortedByNetProfit() {
      // net_profit приходить готовим з JSON (Чистий прибуток після Витрат на ОК).
      // Більше не рахуємо через розподіл витрат Офісу Київ.
      return [...this.storeRows]
          .map(r => {
            const net = this.n(r.net_profit)
            const rev = this.n(r.revenue)
            return {...r, _net: net, _margin: rev > 0 ? net / rev : 0}
          })
          .sort((a, b) => b._net - a._net)
    },

    storesSortedBySalPct() {
      // Обидва показники відповідають рядкам 82-83 оригінального Excel:
      //   _salRev    = salary_pct_profit  — готове значення з JSON (комісійна ЗП / валовий прибуток)
      //   _salProfit = salary / profit    — загальна ЗП / валовий прибуток
      // Виключаємо рядки де salary_pct_profit відсутній (IM, Сервіс) — для них метрика не рахується
      return [...this.storeRows]
          .filter(r => this.n(r.profit) > 0 && r.salary_pct_profit !== '' && r.salary_pct_profit != null)
          .map(r => {
            const profit = this.n(r.profit)
            const op = this.rowOpProfit(r)
            return {
              ...r,
              _op: op,
              _salRev:    this.n(r.salary_pct_profit),          // з JSON напряму
              _salProfit: this.n(r.salary) / profit,            // загальна / прибуток
            }
          })
          .sort((a, b) => this.salSortBy === 'pct'
              ? b._salRev - a._salRev
              : b._salProfit - a._salProfit)
    },

    // ── Filtered stores (search) ──────────────────────────
    filteredStores() {
      const q = this.searchQuery.toLowerCase().trim()
      if (!q) return this.storeRows
      return this.storeRows.filter(r => r.store.toLowerCase().includes(q))
    },
    hBarChartHeight() {
      return Math.max(600, this.storeRows.length * 24) + 'px'
    },
    // Висота графіка ЗП = hprofit-card: padding 8+8 + track 14 + gap 4 + track 14 = 48px на магазин
    salPctMax() {
      if (!this.storesSortedBySalPct.length) return 1
      return Math.max(
          ...this.storesSortedBySalPct.flatMap(r => [r._salRev, r._salProfit]),
          0.01
      )
    },
  },

  watch: {
    async selectedPeriod() {
      // 1. Знищуємо міні-графіки магазинів — вони містять дані старого периоду
      Object.values(this.storeCharts).forEach(c => c.destroy())
      this.storeCharts = markRaw({})
      // 2. Відключаємо старий observer — він вже спостерігав за елементами старого рендеру
      if (this.observer) {
        this.observer.disconnect()
        this.observer = null
      }
      // 3. Чекаємо поки Vue перемалює DOM з новими даними
      await this.$nextTick()
      // 4. Перебудовуємо всі графіки
      this.initCharts()
      this.initStoreCharts()
    },
  },

  async mounted() {
    window.addEventListener('resize', this._onResize)
    await this.loadData()
  },

  beforeUnmount() {
    window.removeEventListener('resize', this._onResize)
    Object.values(this.charts).forEach(c => c.destroy())
    Object.values(this.storeCharts).forEach(c => c.destroy())
    if (this.observer) this.observer.disconnect()
  },

  methods: {
    // ── Утилиты ───────────────────────────────────────────
    n: v => Number(v) || 0,
    fmt: v => Math.round(v).toLocaleString('uk-UA'),
    fmtM: v => {
      const abs = Math.abs(v)
      if (abs >= 1_000_000) return (v / 1_000_000).toFixed(2) + ' млн'
      if (abs >= 1_000) return (v / 1_000).toFixed(1) + ' тис'
      return Math.round(v).toString()
    },
    fmtK: v => Math.abs(v) >= 1000 ? (v / 1000).toFixed(1) + 'т' : Math.round(v).toString(),
    fmtPct: v => (v * 100).toFixed(1) + '%',

    rowExpenses(r) {
      return EXPENSE_FIELDS.reduce((s, f) => s + this.n(r[f]), 0)
    },
    rowOpProfit(r) {
      return this.n(r.profit) - this.rowExpenses(r)
    },
    rowMargin(r) {
      const rev = this.n(r.revenue);
      return rev > 0 ? this.n(r.profit) / rev : 0
    },
    rowProfitability(r) {
      const rev = this.n(r.revenue)
      return rev > 0 ? this.rowOpProfit(r) / rev : 0
    },
    rowProfitabilityAfter(r) {
      // rentab_after приходить готовим з JSON (РЕНТАБЕЛЬНІСТЬ ПІСЛЯ ВІДРАХУВАНЬ НА ОФІС%).
      // Для ІМ та Сервіс Маяковського поле порожнє — повертаємо 0.
      const v = r.rentab_after
      if (v !== '' && v !== null && v !== undefined) return this.n(v)
      return 0
    },

    marginClass(r) {
      const m = this.rowMargin(r) * 100
      if (m >= 25) return 'badge-green'
      if (m >= 15) return 'badge-yellow'
