        utilities: 'Комунальні', logistics: 'Логістика', communication: "Зв'язок",
        bank_fees: 'РКО', writeoffs: 'Втрати', repr_expenses: 'Представницькі',
        repairs: 'Ремонт', tools: 'МШП', salary: 'Оплата праці',
