    _onResize() {
      this.screenWidth = window.innerWidth
    },

    // ── Squarified Treemap ────────────────────────────────
    // Координатна система залежить від орієнтації:
    //   Desktop: 1000×500 (альбомна) — контейнер 460px
    //   Mobile:  500×800 (портретна) — контейнер 680px
    computeTreemapLayout(items, colors, mobile = false) {
      if (!items.length) return []
      const W = mobile ? 500 : 1000
      const H = mobile ? 800 : 500
      const total = items.reduce((s, i) => s + i.value, 0)
      const normed = items.map((i, idx) => ({
        ...i,
        _area: (i.value / total) * W * H,
        color: colors[idx % colors.length],
      }))
      const result = []
      this._tmSquarify(normed, 0, 0, W, H, result)
      return result.map(r => ({
        store:  r.store,
        value:  r.value,
        color:  r.color,
        xPct:   r._x / W * 100,
        yPct:   r._y / H * 100,
        wPct:   r._w / W * 100,
        hPct:   r._h / H * 100,
      }))
    },

    _tmWorst(row, side) {
      if (!row.length || !side) return Infinity
      const s = row.reduce((a, i) => a + i._area, 0)
      const mx = Math.max(...row.map(i => i._area))
      const mn = Math.min(...row.map(i => i._area))
      return Math.max(side * side * mx / (s * s), s * s / (side * side * mn))
    },

    _tmSquarify(items, x, y, w, h, out) {
      if (!items.length) return
      if (items.length === 1) {
        out.push({...items[0], _x: x, _y: y, _w: w, _h: h})
        return
      }
      const side = Math.min(w, h)
      const isWide = w >= h
      let row = []
      let rest = [...items]

      while (rest.length) {
        const next = rest[0]
        const newRow = [...row, next]
        if (!row.length || this._tmWorst(newRow, side) <= this._tmWorst(row, side)) {
          row.push(next)
          rest.shift()
        } else {
          break
        }
      }

      // Якщо жодного елемента не додалось — беремо перший примусово
      if (!row.length) { row.push(rest.shift()) }

      const rowArea = row.reduce((s, i) => s + i._area, 0)

      if (isWide) {
        // Ряд іде зверху вниз, займає смугу зліва
        const colW = rowArea / h
        let py = y
        for (const item of row) {
          const ch = item._area / colW
          out.push({...item, _x: x, _y: py, _w: colW, _h: ch})
          py += ch
        }
        if (rest.length) this._tmSquarify(rest, x + colW, y, w - colW, h, out)
      } else {
        // Ряд іде зліва направо, займає смугу зверху
        const rowH = rowArea / w
        let px = x
        for (const item of row) {
          const cw = item._area / rowH
          out.push({...item, _x: px, _y: y, _w: cw, _h: rowH})
          px += cw
        }
        if (rest.length) this._tmSquarify(rest, x, y + rowH, w, h - rowH, out)
      }
    },

    // ── Загрузка данных ───────────────────────────────────
    async loadData() {
      this.loading = true
      this.error = null
      // Сохраняем предыдущий статус загрузки и блокируем навигацию
      const prevStatus = localStorage.getItem('checkLoadStatus')
      try {
        const res = await fetch(BUDGET_URL)
        const json = await res.json()
        this.rawData = json.budget_info || []
        if (!this.selectedPeriod) {
          const last = this.rawData[this.rawData.length - 1]
          this.selectedPeriod = last?.time || ''
        }
        this.loading = false          // сначала показываем контент
        // Разрешаем навигацию как только данные получены
        localStorage.setItem('checkLoadStatus', 'loaded')
        await this.$nextTick()        // ждём рендер canvas-элементов
        await this.$nextTick()
        this.initCharts()
        this.initStoreCharts()
      } catch (e) {
        this.error = e.message
        this.loading = false
        localStorage.setItem('checkLoadStatus', prevStatus || 'loaded')
      }
    },

    officeBars(store) {
      const COLORS = [
        '#6366f1', '#f59e0b', '#22c55e', '#ef4444', '#14b8a6',
        '#8b5cf6', '#f97316', '#06b6d4', '#ec4899', '#84cc16',
        '#a78bfa', '#fb923c', '#2dd4bf', '#fbbf24', '#64748b',
        '#10b981', '#0ea5e9', '#d946ef', '#e11d48', '#7c3aed',
      ]
      const LABELS = {
        salary: 'Оплата праці', rent: 'Оренда', security: 'Охорона',
        transport: 'Автотранспорт', fuel: 'ПММ', insurance: 'Страхування',
        other_services: 'Послуги інші', utilities: 'Комунальні', logistics: 'Логістика',
        communication: "Зв'язок", bank_fees: 'РКО', writeoffs: 'Втрати/списання',
        repr_expenses: 'Представницькі', repairs: 'Ремонт та запчастини',
        tools: 'МШП', salary_other: 'Інші витрати персоналу',
        salary_travel: 'Відрядження', marketing: 'Маркетинг', taxes: 'Податки',
      }
      const items = EXPENSE_FIELDS
          .map(f => ({label: LABELS[f] || f, value: this.n(store[f])}))
          .filter(i => i.value > 0)
          .sort((a, b) => b.value - a.value)

      const total = items.reduce((s, i) => s + i.value, 0)
      const max = items[0]?.value || 1
      return items.map((item, i) => ({
        ...item,
        color: COLORS[i % COLORS.length],
        pct: Math.round(item.value / max * 100),
        sharePct: (item.value / total * 100).toFixed(1),
      }))
    },

    storePieSegs(store) {
      const PI = Math.PI, cos = Math.cos, sin = Math.sin
      const cx = 60, cy = 60, R = 50, r = 27
      const p = (a, rad) => `${(cx + rad * cos(a)).toFixed(1)},${(cy + rad * sin(a)).toFixed(1)}`

      const COLORS = [
        '#22c55e', '#6366f1', '#f59e0b', '#ef4444', '#14b8a6',
        '#8b5cf6', '#f97316', '#06b6d4', '#ec4899', '#84cc16',
        '#a78bfa', '#fb923c', '#2dd4bf', '#fbbf24', '#f43f5e',
        '#10b981', '#0ea5e9', '#d946ef', '#64748b', '#e11d48', '#7c3aed',
      ]

      const opProfit = this.rowOpProfit(store)

      // Завжди будуємо пиріг відносно валового прибутку (profit).
      // Якщо опер. прибуток > 0 — він перший сегмент.
      // Якщо < 0 — пиріг показує лише структуру витрат (без негативного сегменту),
      //            а в центрі — явне позначення збитку.
      const items = [
        ...(opProfit > 0 ? [{label: 'Оп. прибуток', value: opProfit}] : []),
        {label: 'Оплата праці', value: this.n(store.salary)},
        {label: 'Оренда', value: this.n(store.rent)},
        {label: 'Маркетинг', value: this.n(store.marketing)},
        {label: 'Податки', value: this.n(store.taxes)},
        {label: 'Комунальні', value: this.n(store.utilities)},
        {label: 'Логістика', value: this.n(store.logistics)},
        {label: 'Охорона', value: this.n(store.security)},
        {label: 'ПММ', value: this.n(store.fuel)},
        {label: "Зв'язок", value: this.n(store.communication)},
        {label: 'Послуги інші', value: this.n(store.other_services)},
        {label: 'Втрати/списання', value: this.n(store.writeoffs)},
        {label: 'РКО', value: this.n(store.bank_fees)},
        {label: 'МШП', value: this.n(store.tools)},
        {label: 'Ремонт та запчастини', value: this.n(store.repairs)},
        {label: 'Страхування', value: this.n(store.insurance)},
        {label: 'Автотранспорт', value: this.n(store.transport)},
        {label: 'Представницькі', value: this.n(store.repr_expenses)},
        {label: 'Інші витрати персоналу', value: this.n(store.salary_other)},
        {label: 'Відрядження', value: this.n(store.salary_travel)},
      ]
          .filter(i => i.value > 0)
          .sort((a, b) => b.value - a.value)
          .map((item, i) => ({...item, color: COLORS[i % COLORS.length]}))

      // total = сума всіх сегментів пирога.
      // При opProfit >= 0: total ≈ profit (маржа в центрі відповідає пирогу).
      // При opProfit < 0: total = витрати (показуємо структуру без збиткового сегменту).
      const total = items.reduce((s, i) => s + i.value, 0)
      if (!total) return []
      let angle = -PI / 2

      return items.map(item => {
        const sweep = (item.value / total) * 2 * PI
        const end = angle + sweep
        const large = sweep > PI ? 1 : 0
        const path = `M${p(angle, R)} A${R},${R},0,${large},1,${p(end, R)} L${p(end, r)} A${r},${r},0,${large},0,${p(angle, r)} Z`
        angle = end
        return {...item, path, total, isLoss: opProfit < 0}
      })
    },

    infocardClass(store) {
      const m = this.rowMargin(store)
      if (m >= 0.25) return 'ic-green'
      if (m >= 0.15) return 'ic-amber'
