    storeColsSvg(store) {
      const cols = this.storeColsData(store)
      const chartH = 88
      const baseY = 110
      const colW = 30
      const gap = 9
      const totalW = cols.length * colW + (cols.length - 1) * gap
      const startX = (220 - totalW) / 2

      return cols.map((col, i) => {
        const x = startX + i * (colW + gap)
        const h = Math.max((col.pct / 100) * chartH, 3)
        const y = baseY - h
        return {
          x, y, h, rw: colW,
          cx: x + colW / 2,
          val: this.fmtK(col.value),
          label: col.label,
        }
      })
    },

    storeColsData(store) {
      const items = [
        {
          key: 'salary',
          label: 'ЗП',
          value: this.n(store.salary) + this.n(store.salary_other) + this.n(store.salary_travel),
          colors3d: ['#818cf8', '#c7d2fe', '#4338ca']
        },
        {key: 'rent', label: 'Оренда', value: this.n(store.rent), colors3d: ['#fbbf24', '#fef08a', '#b45309']},
        {key: 'marketing', label: 'Марк.', value: this.n(store.marketing), colors3d: ['#34d399', '#a7f3d0', '#047857']},
        {key: 'taxes', label: 'Подат.', value: this.n(store.taxes), colors3d: ['#f87171', '#fecaca', '#991b1b']},
        {
          key: 'other',
          label: 'Інше',
          value: ['security', 'utilities', 'logistics', 'communication', 'fuel', 'writeoffs', 'bank_fees', 'repr_expenses', 'repairs', 'tools'].reduce((s, f) => s + this.n(store[f]), 0),
          colors3d: ['#2dd4bf', '#99f6e4', '#0f766e']
        },
      ]
      const max = Math.max(...items.map(i => i.value), 1)
      return items.map(i => ({...i, pct: Math.round(i.value / max * 100)}))
    },

    // ── Sal chart helpers ─────────────────────────────────
    salCardClass(store) {
      const p = store._salProfit
      if (p > 1) return 'sal-card--red'
      if (p > 0.6) return 'sal-card--orange'
      if (p > 0.3) return 'sal-card--amber'
