    },

    // ── Modern Flat Donut Chart ───────────────────────────
    buildPie3d(data) {
      if (!data || !data.length) return null
      const total = data.reduce((s, d) => s + d.value, 0)
      if (!total) return null

      const PI = Math.PI, cos = Math.cos, sin = Math.sin
      const W = 320, H = 320
      const cx = 160, cy = 160
      const R = 143        // outer radius
      const r = 80         // inner radius (donut hole)
      const push = 6       // каждый сегмент чуть выдвинут из центра
      const gap = 0.026    // зазор между сегментами (рад)
      const f = v => v.toFixed(2)

      let startA = -PI / 2
      const segs = data.map((item, idx) => {
        const fullSweep = (item.value / total) * 2 * PI
        const sweep = Math.max(fullSweep - gap * 2, 0.02)
        const sA = startA + gap
        const eA = sA + sweep
        const midA = sA + sweep / 2

        // Смещение сегмента от центра
        const dx = push * cos(midA)
        const dy = push * sin(midA)

        // Точки дуг
        const os = {x: cx + dx + R * cos(sA), y: cy + dy + R * sin(sA)}
        const oe = {x: cx + dx + R * cos(eA), y: cy + dy + R * sin(eA)}
        const is = {x: cx + dx + r * cos(sA), y: cy + dy + r * sin(sA)}
        const ie = {x: cx + dx + r * cos(eA), y: cy + dy + r * sin(eA)}
        const large = sweep > PI ? 1 : 0

        const path = [
          `M ${f(os.x)} ${f(os.y)}`,
          `A ${R} ${R} 0 ${large} 1 ${f(oe.x)} ${f(oe.y)}`,
          `L ${f(ie.x)} ${f(ie.y)}`,
          `A ${r} ${r} 0 ${large} 0 ${f(is.x)} ${f(is.y)}`,
          'Z',
        ].join(' ')

        // Метка: по центру толщины кольца
        const labelR = (R + r) / 2
        const lx = cx + dx + labelR * cos(midA)
        const ly = cy + dy + labelR * sin(midA)

        const pct = (item.value / total * 100).toFixed(1)
        const showInside = parseFloat(pct) >= 6

        startA += fullSweep
        return {item, idx, midA, large, path, pct, lx, ly, showInside}
      })

      return {segs, W, H, cx, cy, R, r, total}
    },

    darkenHex(hex, amount = 55) {
      if (!hex || !hex.startsWith('#')) return hex
      const clamp = v => Math.max(0, Math.min(255, v - amount))
      const r = parseInt(hex.slice(1, 3), 16)
      const g = parseInt(hex.slice(3, 5), 16)
      const b = parseInt(hex.slice(5, 7), 16)
      return `rgb(${clamp(r)},${clamp(g)},${clamp(b)})`
    },

    // ── Chart.js инициализация ────────────────────────────
    makeDoughnut(ref, data, labels, colors) {
      const canvas = this.$refs[ref]
      if (!canvas) return null
      if (this.charts[ref]) this.charts[ref].destroy()

      // 3D-shadow plugin: рисуем тень под графиком
      const shadowPlugin = {
        id: 'shadow_' + ref,
        beforeDraw(chart) {
          const {ctx} = chart
          ctx.save()
          ctx.shadowColor = 'rgba(0,0,0,0.18)'
          ctx.shadowBlur = 24
          ctx.shadowOffsetX = 4
          ctx.shadowOffsetY = 8
        },
        afterDraw(chart) {
          chart.ctx.restore()
        },
      }

      const chart = markRaw(new Chart(canvas, {
        type: 'doughnut',
        data: {
          labels,
          datasets: [{
            data,
            backgroundColor: colors,
            borderWidth: 3,
            borderColor: '#fff',
            hoverOffset: 18,
            hoverBorderWidth: 4,
          }],
        },
        options: {
          cutout: '58%',
          responsive: true,
          maintainAspectRatio: true,
          plugins: {
            legend: {display: false},
            tooltip: {
              backgroundColor: 'rgba(15,23,42,0.9)',
              padding: 12,
              cornerRadius: 10,
              callbacks: {
                label: ctx => {
                  const total = ctx.dataset.data.reduce((s, v) => s + v, 0)
                  const pct = total > 0 ? (ctx.raw / total * 100).toFixed(1) : 0
                  return `  ${Math.round(ctx.raw).toLocaleString('uk-UA')} грн (${pct}%)`
                },
              },
            },
          },
          animation: {animateRotate: true, duration: 900, easing: 'easeOutQuart'},
        },
        plugins: [shadowPlugin],
      }))
      this.charts[ref] = chart
      return chart
    },

    makeHBar(ref, labels, datasets, opts = {}) {
      const canvas = this.$refs[ref]
      if (!canvas) return null
      if (this.charts[ref]) this.charts[ref].destroy()
      const chart = markRaw(new Chart(canvas, {
        type: 'bar',
        data: {labels, datasets},
        options: {
          indexAxis: 'y',
          responsive: true,
          maintainAspectRatio: false,
          plugins: {
            legend: {display: false},
            tooltip: {
              callbacks: {
                label: ctx => {
                  const v = ctx.raw
                  if (opts.pct) return ` ${(v * 100).toFixed(1)}%`
                  return ` ${Math.round(v).toLocaleString('uk-UA')} грн`
                },
              },
            },
          },
          scales: {
            x: {
              grid: {color: 'rgba(0,0,0,0.05)'},
              ticks: {
                callback: v => opts.pct ? (v * 100).toFixed(0) + '%' : (Math.abs(v) >= 1e6 ? (v / 1e6).toFixed(1) + 'м' : (v / 1000).toFixed(0) + 'т'),
                font: {size: 10},
              },
            },
            y: {
              grid: {display: false},
              ticks: {font: {size: 10}},
            },
          },
          animation: {duration: 600},
        },
      }))
      this.charts[ref] = chart
      return chart
    },

    makeVBar(ref, labels, datasets, opts = {}) {
      const canvas = this.$refs[ref]
      if (!canvas) return null
      if (this.charts[ref]) this.charts[ref].destroy()

      const isH = opts.indexAxis === 'y'

      const fmtV = v => opts.fullNum
          ? Math.round(v).toLocaleString('uk-UA')
          : opts.pct
              ? (v * 100).toFixed(1) + '%'
              : Math.abs(v) >= 1e6 ? (v / 1e6).toFixed(2) + 'м'
                  : Math.abs(v) >= 1e3 ? (v / 1e3).toFixed(1) + 'т'
                      : Math.round(v).toString()

      // Плагін підписів — горизонтальний або вертикальний режим
      const datalabels = {
        id: 'vbar_datalabels_' + ref,
        afterDatasetsDraw(chart) {
          const {ctx} = chart
          chart.data.datasets.forEach((ds, dsIdx) => {
            if (!chart.isDatasetVisible(dsIdx)) return
            chart.getDatasetMeta(dsIdx).data.forEach((bar, idx) => {
              const v = ds.data[idx]
              if (v == null) return
              const label = fmtV(v)
              ctx.save()
              ctx.fillStyle = '#334155'
              ctx.font = `bold ${datasets.length > 1 ? 8 : 9}px Arial, sans-serif`
              if (isH) {
                // Підпис праворуч від бару
                ctx.textAlign = v >= 0 ? 'left' : 'right'
                ctx.textBaseline = 'middle'
                ctx.fillText(label, v >= 0 ? bar.x + 4 : bar.x - 4, bar.y)
              } else {
                const angle = opts.angle ?? -Math.PI / 2
                ctx.translate(bar.x, v >= 0 ? bar.y - 4 : bar.y + 4)
                ctx.rotate(angle)
                ctx.textAlign = v >= 0 ? 'left' : 'right'
                ctx.textBaseline = 'middle'
                ctx.fillText(label, 0, 0)
              }
              ctx.restore()
            })
          })
        },
      }

      const chart = markRaw(new Chart(canvas, {
        type: 'bar',
        data: {labels, datasets},
        options: {
          indexAxis: opts.indexAxis || 'x',
          responsive: true,
          maintainAspectRatio: false,
          layout: {
            padding: isH
                ? {top: 8, right: 52, left: 4, bottom: 8}
                : {top: 52, right: 12, left: 4, bottom: 4},
          },
          plugins: {
            legend: {
              display: datasets.length > 1,
              position: 'top',
              labels: {
                font: {size: 11},
                padding: 16,
                // legendColors задаёт фиксированные цвета для легенды
                // (нужно когда backgroundColor — массив per-bar цветов)
                generateLabels: opts.legendColors
                    ? (chart) => chart.data.datasets.map((ds, i) => ({
                      text: ds.label,
                      fillStyle: opts.legendColors[i] || '#94a3b8',
                      strokeStyle: opts.legendColors[i] || '#94a3b8',
                      lineWidth: 2,
                      hidden: !chart.isDatasetVisible(i),
                      datasetIndex: i,
                    }))
                    : undefined,
              },
            },
            tooltip: {
              backgroundColor: 'rgba(15,23,42,0.9)',
              padding: 10, cornerRadius: 8,
              callbacks: {label: ctx => '  ' + fmtV(ctx.raw)},
            },
          },
          scales: isH ? {
            // Горизонтальний режим: x — значення, y — магазини
            x: {
              grid: {color: 'rgba(0,0,0,0.05)'},
              ticks: {font: {size: 10}, color: '#64748b', callback: v => fmtV(v)},
            },
            y: {
              grid: {display: false},
              ticks: {font: {size: 10}, color: '#475569'},
            },
          } : {
            // Вертикальний режим (стандартний)
            x: {
              grid: {display: false},
              ticks: {maxRotation: 90, minRotation: 90, font: {size: 9}, color: '#64748b'},
            },
            y: {
              grid: {color: 'rgba(0,0,0,0.05)'},
              ticks: {font: {size: 10}, color: '#64748b', callback: v => fmtV(v)},
            },
          },
          animation: {duration: 700, easing: 'easeOutQuart'},
        },
        plugins: [datalabels],
      }))
      this.charts[ref] = chart
      return chart
    },

    makeLineChart(ref, labels, datasets) {
      const canvas = this.$refs[ref]
      if (!canvas) return null
      if (this.charts[ref]) this.charts[ref].destroy()

      const fmtV = v => (v * 100).toFixed(1) + '%'

      // Кольорові зони на фоні
      const zones = {
        id: 'zones_' + ref,
        beforeDraw(chart) {
          const {ctx, chartArea: {left, right}, scales: {y}} = chart
          const bands = [
            {from: 0, to: 0.25, color: 'rgba(34,197,94,0.06)'},
            {from: 0.25, to: 0.35, color: 'rgba(245,158,11,0.08)'},
            {from: 0.35, to: 0.50, color: 'rgba(249,115,22,0.08)'},
            {from: 0.50, to: 1.00, color: 'rgba(239,68,68,0.10)'},
          ]
          ctx.save()
          bands.forEach(({from, to, color}) => {
            const yFrom = y.getPixelForValue(to)
            const yTo = y.getPixelForValue(from)
            ctx.fillStyle = color
            ctx.fillRect(left, yFrom, right - left, yTo - yFrom)
          })
          // Лінії меж зон
          ;[0.25, 0.35, 0.50].forEach(val => {
            const py = y.getPixelForValue(val)
            ctx.strokeStyle = 'rgba(0,0,0,0.08)'
            ctx.lineWidth = 1
            ctx.setLineDash([4, 4])
            ctx.beginPath();
            ctx.moveTo(left, py);
            ctx.lineTo(right, py);
            ctx.stroke()
          })
          ctx.setLineDash([])
          ctx.restore()
        },
      }

      // Підписи на точках — над лінією, кожна друга
      const pointLabels = {
        id: 'lineLabels_' + ref,
        afterDatasetsDraw(chart) {
          const {ctx} = chart
          chart.data.datasets.forEach((ds, dsIdx) => {
            if (!chart.isDatasetVisible(dsIdx)) return
            chart.getDatasetMeta(dsIdx).data.forEach((point, idx) => {
              const v = ds.data[idx]
              if (v == null) return
              ctx.save()
              ctx.fillStyle = ds.borderColor
              ctx.font = 'bold 9px Arial, sans-serif'
              ctx.textAlign = 'center'
              ctx.textBaseline = 'bottom'
              ctx.fillText(fmtV(v), point.x, point.y - 8)
              ctx.restore()
            })
          })
        },
      }

      const chart = markRaw(new Chart(canvas, {
        type: 'line',
        data: {labels, datasets},
        options: {
          responsive: true,
          maintainAspectRatio: false,
          layout: {padding: {top: 32, right: 12, left: 8, bottom: 8}},
          plugins: {
            legend: {display: false},
            tooltip: {
              backgroundColor: 'rgba(15,23,42,0.9)',
              padding: 10, cornerRadius: 8,
              callbacks: {label: ctx => `  ${ctx.dataset.label}: ${fmtV(ctx.raw)}`},
            },
          },
          scales: {
            x: {
              grid: {display: false},
              ticks: {maxRotation: 90, minRotation: 90, font: {size: 9}, color: '#64748b'},
            },
            y: {
              min: 0, max: 0.7,
              grid: {display: false},
              ticks: {font: {size: 10}, color: '#64748b', callback: v => (v * 100).toFixed(0) + '%', stepSize: 0.1},
            },
          },
          animation: {duration: 700},
        },
        plugins: [zones, pointLabels],
      }))
      this.charts[ref] = chart
      return chart
    },

    initCharts() {
      // 8. Маржинальність (horizontal)
      const margRows = this.storesSortedByMargin
      this.makeVBar('chartMargin', margRows.map(r => r.store), [{
        data: margRows.map(r => r._margin),
        backgroundColor: margRows.map(r =>
            r._margin >= 0.25 ? 'rgba(34,197,94,0.85)' :
                r._margin >= 0.15 ? 'rgba(245,158,11,0.85)' : 'rgba(239,68,68,0.85)'),
        borderRadius: 4, borderSkipped: false, label: 'Маржинальність',
      }], {pct: true, indexAxis: 'y'})
      // 9. Рентабельність (horizontal, 2 серії)
      const rentRows = this.storesSortedByRentab
      this.makeVBar('chartRentab', rentRows.map(r => r.store), [
        {
          data: rentRows.map(r => r._rentab),
          backgroundColor: 'rgba(99,102,241,0.85)',
          borderRadius: 3,
          label: 'Рентабельність %'
        },
        {
          data: rentRows.map(r => r._rentabAfter),
          backgroundColor: 'rgba(20,184,166,0.75)',
          borderRadius: 3,
          label: 'Після офісу %'
        },
      ], {pct: true, indexAxis: 'y'})
      // 10-11. Тепер HTML-компонент, Chart.js не потрібен
      // 13. Офіс Київ
      if (this.ofisKyiv) {
        this.makeDoughnut('chartOfis',
            this.ofisData.map(d => d.value),
            this.ofisData.map(d => d.label),
            this.ofisData.map(d => d.color),
        )
      }
      // 14. Склад Київ
      if (this.skladKyiv) {
        this.makeDoughnut('chartSklad',
            this.skladData.map(d => d.value),
            this.skladData.map(d => d.label),
            this.skladData.map(d => d.color),
        )
      }
    },

    // Мини-пироги по магазинам (создаём ленив через IntersectionObserver)
    initStoreCharts() {
      if (!('IntersectionObserver' in window)) {
        this.storeRows.forEach(r => this.createStoreChart(r.store))
        return
      }
      this.$nextTick(() => {
        this.observer = new IntersectionObserver((entries) => {
          entries.forEach(entry => {
            if (entry.isIntersecting) {
              const store = entry.target.dataset.store
              if (store && !this.storeCharts[store]) {
                this.createStoreChart(store)
              }
            }
          })
        }, {rootMargin: '300px'})
        document.querySelectorAll('.store-pie-wrap[data-store]').forEach(el => {
          this.observer.observe(el)
        })
      })
    },

    createStoreChart(storeName) {
      const ref = `sc_${storeName}`
      const canvas = this.$refs[ref]
      if (!canvas || this.storeCharts[storeName]) return
      const row = this.storeRows.find(r => r.store === storeName)
      if (!row) return
      const items = [
        {label: 'ЗП', value: this.n(row.salary)},
        {label: 'Оренда', value: this.n(row.rent)},
        {label: 'Маркетинг', value: this.n(row.marketing)},
        {label: 'Податки', value: this.n(row.taxes)},
        {label: 'Комунальні', value: this.n(row.utilities)},
        {label: 'Логістика', value: this.n(row.logistics)},
        {
          label: 'Інше',
          value: ['transport', 'fuel', 'insurance', 'other_services', 'communication', 'bank_fees', 'writeoffs', 'repr_expenses', 'repairs', 'tools', 'salary_other', 'salary_travel'].reduce((s, f) => s + this.n(row[f]), 0)
        },
      ].filter(i => i.value > 0)
      const chart = markRaw(new Chart(canvas, {
        type: 'doughnut',
        data: {
          labels: items.map(i => i.label),
          datasets: [{
            data: items.map(i => i.value),
            backgroundColor: PIE_COLORS,
            borderWidth: 1, borderColor: '#fff',
          }],
        },
        options: {
          cutout: '55%', responsive: true, maintainAspectRatio: false,
          plugins: {
            legend: {display: false},
            tooltip: {callbacks: {label: ctx => ` ${Math.round(ctx.raw).toLocaleString('uk-UA')} грн`}}
          },
          animation: {duration: 500},
        },
      }))
      this.storeCharts[storeName] = chart
    },
  },
}
</script>

